import{_ as r,r as t,o as i,c as s,e as o,a as l,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Exploring the Backend - October CMS User Guide","titleTemplate":false,"description":"Log in and explore the main areas of the backend","frontmatter":{"subtitle":"Log in and explore the main areas of the backend"},"headers":[{"level":2,"title":"Log In","slug":"log-in","link":"#log-in","children":[]},{"level":2,"title":"Look Around the Main Menu","slug":"look-around-the-main-menu","link":"#look-around-the-main-menu","children":[]},{"level":2,"title":"Check Your Profile","slug":"check-your-profile","link":"#check-your-profile","children":[]},{"level":2,"title":"Try a Keyboard Shortcut","slug":"try-a-keyboard-shortcut","link":"#try-a-keyboard-shortcut","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/backend/backend-tour.md","filePath":"user-guide/quickstart/backend/backend-tour.md"}'),h={name:"user-guide/quickstart/backend/backend-tour.md"};function u(c,e,g,p,m,y){const a=t("pre-heading"),n=t("post-heading");return i(),s("div",null,[o(a),e[0]||(e[0]=l("h1",null,"Exploring the Backend",-1)),o(n),e[1]||(e[1]=d(`<p>The backend is your control center. This is where you manage pages, content, media, settings, and everything else about your site. Let&#39;s log in and take a quick tour.</p><h2 id="log-in"><a href="#log-in" class="header-anchor">#</a> Log In</h2><p>Open your browser and navigate to your site&#39;s URL followed by <code>/admin</code>:</p><div class="language- extra-class"><pre class="language-text"><code>http://localhost:8000/admin
</code></pre></div><p>Enter the administrator username and password you created during installation. After logging in, you will land on the <strong>Dashboard</strong>.</p><h2 id="look-around-the-main-menu"><a href="#look-around-the-main-menu" class="header-anchor">#</a> Look Around the Main Menu</h2><p>The main navigation runs along the top of the screen. Click through each section to see what is there:</p><ol><li><strong>Dashboard</strong>: your home base. It shows widgets with at-a-glance information about your site. We will customize this in the next article.</li><li><strong>Editor</strong>: click into this section. You will see <strong>Pages</strong>, <strong>Layouts</strong>, <strong>Partials</strong>, and <strong>Content</strong> in the side panel. This is where you build and edit your site&#39;s templates.</li><li><strong>Media</strong>: your file manager. Click into it and you will see an empty library. This is where you upload images, documents, and other files.</li><li><strong>Settings</strong>: the configuration area. Click through a few items to get a sense of what is here, including administrator management, mail settings, updates, and more.</li></ol><p>Don&#39;t worry about memorizing everything. The goal right now is just to know what lives where.</p><div class="custom-block tip"><p>As you install plugins, new menu items may appear in the top navigation. For example, a blog plugin would add a &quot;Blog&quot; section. The navigation grows with your site.</p></div><h2 id="check-your-profile"><a href="#check-your-profile" class="header-anchor">#</a> Check Your Profile</h2><ol><li>Click your name (or avatar) in the top-right corner of the backend.</li><li>Select <strong>My Account</strong> from the dropdown.</li><li>This is where you can change your password, upload an avatar, and set your preferred language.</li><li>Click <strong>Back</strong> or navigate away when you are done looking.</li></ol><h2 id="try-a-keyboard-shortcut"><a href="#try-a-keyboard-shortcut" class="header-anchor">#</a> Try a Keyboard Shortcut</h2><p>While you are here, try pressing <strong>Ctrl+S</strong> (or <strong>Cmd+S</strong> on macOS) in any editor. This saves the current page. It&#39;s a small thing, but it will save you a lot of mouse clicks as you work.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Now that you know your way around, let&#39;s customize your dashboard. Continue to <a href="./dashboard.html">Dashboard &amp; Statistics</a> to rearrange widgets and generate some sample data.</p>`,16))])}const w=r(h,[["render",u]]);export{f as __pageData,w as default};
